import {mainQuery} from '@github-ui/react-core/future/main-query'
import {customRolesAppBuilder} from '../config/app-builder'
import type {CustomRolePayload} from '../types'

export const customEnterpriseOwnedOrgRolesRoute = customRolesAppBuilder.createQueryRouteConfig(
  'customEnterpriseOwnedOrgRolesRoute',
  {
    path: '/enterprises/:slug/org_roles/:action',
    queries: [mainQuery<CustomRolePayload>()],
  },
)

export const customEnterpriseOwnedOrgRolesEditRoute = customRolesAppBuilder.createQueryRouteConfig(
  'customEnterpriseOwnedOrgRolesEditRoute',
  {
    path: '/enterprises/:slug/org_roles/:role_id/:action',
    queries: [mainQuery<CustomRolePayload>()],
  },
)
