import {useCallback, useState} from 'react'
import {announce} from '@github-ui/aria-live'
import {
  BaseRole,
  TargetType,
  type BaseRolesByTargetType,
  type Permission,
  type PermissionsByBaseRole,
  type PermissionsByTargetType,
  type RequiredPermissionsByTargetType,
} from '../../types'
import {SimpleListView} from '@github-ui/simple-list-view'
import {PermissionsList} from './PermissionsList'
import {PermissionsPickerHeader} from './PermissionsPickerHeader'
import {getBaseRoleDisplayName} from './BaseRoleMenu'

export interface PermissionsPickerProps {
  availablePermissions: PermissionsByTargetType
  availableBaseRoles?: BaseRolesByTargetType
  targetTypes: TargetType[]
  selectedFgpsByTarget: RequiredPermissionsByTargetType<TargetType[]>
  setSelectedFgpsByTarget: React.Dispatch<React.SetStateAction<RequiredPermissionsByTargetType<TargetType[]>>>
  selectedBaseRoleByTarget: Partial<Record<TargetType, BaseRole>>
  setSelectedBaseRoleByTarget: React.Dispatch<React.SetStateAction<Partial<Record<TargetType, BaseRole>>>>
}

// Function to group available permissions by base role for each target type
function useGroupBaseRolePermissions(
  availablePermissions: PermissionsByTargetType,
  availableBaseRoles?: BaseRolesByTargetType,
  targetTypes: TargetType[] = [],
) {
  return useCallback(() => {
    const grouped: Partial<Record<TargetType, Record<BaseRole, Permission[]>>> = {}

    for (const targetType of targetTypes) {
      const baseRoles = availableBaseRoles?.[targetType] || []
      if (baseRoles.length === 0) continue

      const filteredPermissions = (availablePermissions[targetType] ?? []).filter(
        permission => permission.baseRole && baseRoles.includes(permission.baseRole),
      )
      const permissionsByBaseRole: PermissionsByBaseRole = filteredPermissions.reduce<PermissionsByBaseRole>(
        (acc, permission) => {
          const key = permission.baseRole || BaseRole.None
          const list = acc[key]
          if (list) {
            list.push(permission)
          } else {
            acc[key] = [permission]
          }
          return acc
        },
        Object.create(null) as PermissionsByBaseRole,
      )

      grouped[targetType] = permissionsByBaseRole as Record<BaseRole, Permission[]>
    }

    return grouped
  }, [availablePermissions, availableBaseRoles, targetTypes])
}

// Function to calculate base role's permissions using pre-grouped data
function calculateBaseRolePermissions(
  groupedPermissions: Partial<Record<TargetType, Record<BaseRole, Permission[]>>>,
  availableBaseRoles?: BaseRolesByTargetType,
) {
  return (targetType: TargetType, baseRole?: BaseRole): Permission[] => {
    if (!baseRole) return []

    const availableRoles = availableBaseRoles?.[targetType] || []

    if (!groupedPermissions[targetType]) return []

    const permissions = Object.entries(groupedPermissions[targetType])
      .filter(([role]) => availableRoles.indexOf(role as BaseRole) <= availableRoles.indexOf(baseRole))
      .flatMap(([, p]) => p)

    // Sort permissions by base role order
    return permissions.sort((a, b) => {
      const aIndex = a.baseRole ? availableRoles.indexOf(a.baseRole) : availableRoles.length
      const bIndex = b.baseRole ? availableRoles.indexOf(b.baseRole) : availableRoles.length
      return aIndex - bIndex
    })
  }
}

// Custom hook to process available permissions, adding Admin base role where applicable
function useProcessedPermissions(
  availablePermissions: PermissionsByTargetType,
  availableBaseRoles?: BaseRolesByTargetType,
  targetTypes: TargetType[] = [],
) {
  return useCallback(() => {
    const processed: PermissionsByTargetType = {}

    for (const targetType of targetTypes) {
      const permissions = availablePermissions[targetType] ?? []
      const availableRoles = availableBaseRoles?.[targetType] ?? []
      const hasAdminRole = availableRoles.includes(BaseRole.Admin)

      if (hasAdminRole) {
        // Add Admin base role to permissions that don't have a base role
        processed[targetType] = permissions.map(permission => {
          if (!permission.baseRole) {
            return {
              ...permission,
              baseRole: BaseRole.Admin,
            }
          }
          return permission
        })
      } else {
        processed[targetType] = permissions
      }
    }

    return processed
  }, [availablePermissions, availableBaseRoles, targetTypes])
}

export function PermissionsPicker({
  availablePermissions,
  availableBaseRoles,
  targetTypes,
  selectedFgpsByTarget,
  setSelectedFgpsByTarget,
  selectedBaseRoleByTarget,
  setSelectedBaseRoleByTarget,
}: PermissionsPickerProps) {
  const getProcessedPermissions = useProcessedPermissions(availablePermissions, availableBaseRoles, targetTypes)
  const processedPermissions = getProcessedPermissions()

  const getGroupedPermissions = useGroupBaseRolePermissions(processedPermissions, availableBaseRoles, targetTypes)
  const groupedPermissions = getGroupedPermissions()

  const getBaseRolePermissions = useCallback(
    (targetType: TargetType, baseRole?: BaseRole) => {
      if (!baseRole) return []

      const calculate = calculateBaseRolePermissions(groupedPermissions, availableBaseRoles)
      return calculate(targetType, baseRole)
    },
    [groupedPermissions, availableBaseRoles],
  )

  const [selectedTargetType, setSelectedTargetType] = useState<TargetType>(targetTypes[0] || TargetType.Repository)

  const setSelectedFgpsForCurrentTarget = useCallback(
    (fgps: Permission[] | ((prev: Permission[]) => Permission[])) => {
      setSelectedFgpsByTarget(prev => ({
        ...prev,
        [selectedTargetType]: typeof fgps === 'function' ? fgps(prev[selectedTargetType]) : fgps,
      }))
    },
    [selectedTargetType, setSelectedFgpsByTarget],
  )

  const setSelectedBaseRoleForCurrentTarget = useCallback(
    (baseRole: BaseRole) => {
      setSelectedBaseRoleByTarget(prev => ({
        ...prev,
        [selectedTargetType]: baseRole,
      }))

      if (baseRole === BaseRole.None) {
        // Clear all selected permissions
        setSelectedFgpsByTarget(prev => ({
          ...prev,
          [selectedTargetType]: [],
        }))

        // The announcement is delayed to allow screen readers to prioritize focus changes (when the BaseRoleMenu is closed) first
        setTimeout(() => {
          announce('Base role set to None. All permissions cleared.')
        }, 1000)
      } else {
        // Remove any selected permissions that are included in the new base role
        const currentAvailableBaseRoles = availableBaseRoles?.[selectedTargetType] || []

        setSelectedFgpsByTarget(prev => ({
          ...prev,
          [selectedTargetType]: prev[selectedTargetType].filter(
            permission =>
              !permission.baseRole ||
              currentAvailableBaseRoles.indexOf(permission.baseRole) > currentAvailableBaseRoles.indexOf(baseRole),
          ),
        }))

        const permissionCount = getBaseRolePermissions(selectedTargetType, baseRole).length
        const roleName = getBaseRoleDisplayName(baseRole)
        // The announcement is delayed to allow screen readers to prioritize focus changes (when the BaseRoleMenu is closed) first
        setTimeout(() => {
          announce(
            `${permissionCount} ${
              permissionCount === 1 ? 'permission' : 'permissions'
            } inherited from the ${roleName} base role.`,
          )
        }, 1000)
      }
    },
    [
      availableBaseRoles,
      selectedTargetType,
      setSelectedBaseRoleByTarget,
      setSelectedFgpsByTarget,
      getBaseRolePermissions,
    ],
  )

  function getCurrentTargetData() {
    const selectedFgps = selectedFgpsByTarget[selectedTargetType]
    const currentAvailableBaseRoles = availableBaseRoles?.[selectedTargetType] || []
    const baseRole = selectedBaseRoleByTarget[selectedTargetType]
    const baseRolePermissions = getBaseRolePermissions(selectedTargetType, baseRole)

    const availableFgps = (processedPermissions[selectedTargetType] ?? []).filter(
      permission => !baseRolePermissions.includes(permission),
    )

    return {
      selectedFgps,
      currentAvailableBaseRoles,
      baseRole,
      baseRolePermissions,
      availableFgps,
    }
  }

  function getPermissionCountsByTarget() {
    return targetTypes.reduce(
      (acc, type) => {
        const selectedBaseRole = selectedBaseRoleByTarget[type]
        const baseRolePermissions = getBaseRolePermissions(type, selectedBaseRole)
        const selectedPermissions = selectedFgpsByTarget[type]
        acc[type] = baseRolePermissions.length + selectedPermissions.length
        return acc
      },
      {} as Record<TargetType, number>,
    )
  }

  if (targetTypes.length === 0) {
    return null
  }

  const currentData = getCurrentTargetData()
  const permissionCounts = getPermissionCountsByTarget()

  return (
    <SimpleListView>
      <PermissionsPickerHeader
        targetType={{
          selected: selectedTargetType,
          available: targetTypes,
          onSelect: setSelectedTargetType,
        }}
        permissions={{
          selected: currentData.selectedFgps,
          available: currentData.availableFgps,
          countsByTarget: permissionCounts,
          onSelect: setSelectedFgpsForCurrentTarget,
        }}
        baseRole={
          currentData.currentAvailableBaseRoles.length > 0
            ? {
                available: currentData.currentAvailableBaseRoles,
                selected: currentData.baseRole,
                onSelect: setSelectedBaseRoleForCurrentTarget,
              }
            : undefined
        }
      />
      <PermissionsList
        targetType={selectedTargetType}
        selectedFgps={currentData.selectedFgps}
        setSelectedFgps={setSelectedFgpsForCurrentTarget}
        baseRoleFgps={currentData.baseRolePermissions}
        noBaseRoleSelected={
          (currentData.baseRole === BaseRole.None || currentData.baseRole === undefined) &&
          currentData.currentAvailableBaseRoles.length > 0
        }
      />
    </SimpleListView>
  )
}
