import {Button, SelectPanel} from '@primer/react'
import type {Permission, TargetType} from '../../types'
import {PlusIcon} from '@primer/octicons-react'
import {useState, useCallback} from 'react'
import type {ActionListGroupedListProps, ActionListItemInput as ItemInput} from '@primer/react/deprecated'

export interface PermissionsSelectPanelProps {
  targetType: TargetType
  availableFgps: Permission[]
  selectedFgps: Permission[]
  setSelectedFgps: (fgps: Permission[]) => void
}

function isPermissionSelected(permission: Permission, selectedItems: ItemInput[]): boolean {
  return selectedItems.some(item => item.id === permission.label)
}

function isItemSelected(item: ItemInput, selectedPermissions: Permission[]): boolean {
  return selectedPermissions.some(permission => permission.label === item.id)
}

export function PermissionsSelectPanel({
  targetType,
  availableFgps,
  selectedFgps,
  setSelectedFgps,
}: PermissionsSelectPanelProps) {
  const [open, setOpen] = useState(false)
  const [filter, setFilter] = useState('')

  const items: ItemInput[] = availableFgps.map(fgp => ({
    text: fgp.description,
    id: fgp.label,
    groupId: fgp.category,
  }))

  const selected: ItemInput[] = items.filter(item => isItemSelected(item, selectedFgps))
  const filteredItems = items.filter(item => item.text?.toLowerCase().includes(filter.toLowerCase()))

  // make groups of fgp categories of filteredItems (do not show empty categories when filtering)
  const categories: string[] = Array.from(
    new Set(filteredItems.map(fgp => fgp.groupId).filter((groupId): groupId is string => Boolean(groupId))),
  )
  const groupMetadata: ActionListGroupedListProps['groupMetadata'] = categories.map(category => ({
    groupId: category,
    header: {title: category, variant: 'filled'},
  }))

  const onSelectedChange = useCallback(
    (selectedItems: ItemInput[]) => {
      const selectedPermissions = availableFgps.filter(fgp => isPermissionSelected(fgp, selectedItems))
      setSelectedFgps(selectedPermissions)
    },
    [availableFgps, setSelectedFgps],
  )

  return (
    // The lint rule thinks `width` is a system prop but it's actually a custom prop
    // eslint-disable-next-line primer-react/no-system-props
    <SelectPanel
      title={`Select ${targetType.toLowerCase()} permissions`}
      renderAnchor={({...anchorProps}) => (
        <Button {...anchorProps} aria-haspopup="dialog" leadingVisual={PlusIcon}>
          Add permissions
        </Button>
      )}
      onOpenChange={setOpen}
      open={open}
      items={filteredItems}
      groupMetadata={groupMetadata}
      placeholderText="Search"
      onFilterChange={setFilter}
      selected={selected}
      onSelectedChange={onSelectedChange}
      width="large"
      overlayProps={{maxHeight: 'large'}}
    />
  )
}
