import {testIdProps} from '@github-ui/test-id-props'
import {TextInput, FormControl, Textarea, Button, Stack, Text} from '@primer/react'
import {useState} from 'react'
import styles from './CustomRoleForm.module.css'
import {useMutation} from '@github-ui/react-query'
import {createOrUpdateCustomRole} from '../routes/mutations'
import {useBannerContext} from '@github-ui/role-assignments/banner-provider'
import {
  BaseRole,
  TARGET_TYPE_ORDER,
  TargetType,
  type BaseRolesByTargetType,
  type PermissionsByTargetType,
  type RequiredPermissionsByTargetType,
  type Role,
} from '../types'
import {PermissionsPicker} from './PermissionsPicker/PermissionsPicker'
import {RoleUpdateConfirmationDialog} from './RoleUpdateConfirmationDialog/RoleUpdateConfirmationDialog'

interface CustomRoleFormProps {
  cancelButtonText?: string
  basePath: string
  role?: Role | undefined
  addPermissionsText?: string
  availablePermissions: PermissionsByTargetType
  availableBaseRoles?: BaseRolesByTargetType
}

// Custom hook to manage state for selected permissions and base roles
function usePermissionsState(targetTypes: TargetType[], availableBaseRoles?: BaseRolesByTargetType, role?: Role) {
  const [selectedFgpsByTarget, setSelectedFgpsByTarget] = useState<RequiredPermissionsByTargetType<typeof targetTypes>>(
    () => {
      return targetTypes.reduce(
        (acc, type) => {
          acc[type] = role?.selectedPermissions?.[type] ?? []
          return acc
        },
        {} as RequiredPermissionsByTargetType<typeof targetTypes>,
      )
    },
  )

  const [selectedBaseRoleByTarget, setSelectedBaseRoleByTarget] = useState<Partial<Record<TargetType, BaseRole>>>(
    () => {
      const initialBaseRoles: Partial<Record<TargetType, BaseRole>> = {}
      for (const type of targetTypes) {
        const selectedValue = role?.selectedBaseRole?.[type]
        const defaultValue = availableBaseRoles?.[type]?.[0]
        if (selectedValue || defaultValue) {
          initialBaseRoles[type] = selectedValue ?? defaultValue
        }
      }
      return initialBaseRoles
    },
  )

  return {
    selectedFgpsByTarget,
    setSelectedFgpsByTarget,
    selectedBaseRoleByTarget,
    setSelectedBaseRoleByTarget,
  }
}

function getAvailableTargetTypes(availablePermissions: PermissionsByTargetType): TargetType[] {
  return Object.keys(availablePermissions)
    .filter(type => (availablePermissions[type as TargetType] ?? []).length > 0)
    .sort(
      (a, b) => TARGET_TYPE_ORDER.indexOf(a as TargetType) - TARGET_TYPE_ORDER.indexOf(b as TargetType),
    ) as TargetType[]
}

export function CustomRoleForm({
  cancelButtonText = 'Cancel',
  basePath,
  role,
  addPermissionsText = 'Add permissions to create a role that fits your needs.',
  availablePermissions,
  availableBaseRoles,
}: CustomRoleFormProps) {
  const [validationError, setValidationError] = useState<string | undefined>(undefined)
  const [isConfirmationDialogOpen, setIsConfirmationDialogOpen] = useState(false)
  const initialName = role?.name || ''
  const initialDescription = role?.description || ''
  const submitButtonText = role ? 'Update role' : 'Create role'
  const [name, setName] = useState(initialName)
  const [description, setDescription] = useState(initialDescription)
  const targetTypes = getAvailableTargetTypes(availablePermissions)
  const {selectedFgpsByTarget, setSelectedFgpsByTarget, selectedBaseRoleByTarget, setSelectedBaseRoleByTarget} =
    usePermissionsState(targetTypes, availableBaseRoles, role)
  const {navigate, showBanner} = useBannerContext()

  const {mutate, isSuccess, isPending} = useMutation({
    mutationFn: createOrUpdateCustomRole,
    onSuccess: data => {
      if (data.success) {
        navigate(basePath)
      } else {
        showBanner({
          message: data.message,
          variant: 'critical',
        })
      }
    },
    onError: (error: Error & {data?: {message?: string}}) => {
      const message =
        error.data?.message ||
        `Something went wrong ${role ? 'updating' : 'creating'} the role. Please try again later.`
      showBanner({
        message,
        variant: 'critical',
      })
      // Close dialog on error so banner can be seen on the form
      setIsConfirmationDialogOpen(false)
    },
  })

  function validateForm(): boolean {
    setValidationError(undefined)
    if (name.trim() === '') {
      setValidationError('Name is required')
      return false
    }
    return true
  }

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    if (!validateForm()) return

    if (role) {
      // For edit: open confirmation dialog
      setIsConfirmationDialogOpen(true)
    } else {
      // For create: submit directly
      performSubmit()
    }
  }

  function handleCancel() {
    setName('')
    setDescription('')
    setValidationError(undefined)
    navigate(basePath)
  }

  async function performSubmit() {
    const fgps = Object.values(selectedFgpsByTarget).flatMap(target => target.map(fgp => fgp.label))
    const baseRepoRole = selectedBaseRoleByTarget[TargetType.Repository]

    // Create base payload
    const payload: {
      path: string
      name: string
      description: string
      fgps: string[]
      base_role?: string
      roleId?: number
    } = {
      path: basePath,
      name,
      description,
      fgps,
      roleId: role?.id,
    }

    // Only include base_role if it's set and not None
    if (baseRepoRole && baseRepoRole !== BaseRole.None) {
      payload.base_role = baseRepoRole
    }

    mutate(payload)
  }

  return (
    <>
      <form id="custom-role-form" onSubmit={handleSubmit} {...testIdProps('custom-role-form')}>
        <Stack gap="spacious" className={styles.Stack}>
          <Stack gap="normal">
            <FormControl required id="name-input">
              <FormControl.Label>Name</FormControl.Label>
              <TextInput
                className={styles.NameInput}
                placeholder="Role name"
                value={name}
                onChange={e => {
                  setName(e.target.value)
                  // Clear validation error when user starts typing
                  if (validationError && e.target.value.trim() !== '') {
                    setValidationError(undefined)
                  }
                }}
              />
              {validationError && (
                <FormControl.Validation variant="error">
                  <span data-testid="custom-role-name-error">{validationError}</span>
                </FormControl.Validation>
              )}
            </FormControl>
            <div className="width-full">
              <FormControl id="description-input">
                <FormControl.Label>Description</FormControl.Label>
                <Textarea
                  className={styles.DescriptionInput}
                  placeholder="What is this role all about?"
                  value={description}
                  onChange={e => setDescription(e.target.value)}
                  rows={4}
                />
                <FormControl.Caption>
                  A short description who this role is for or what permissions it grants.
                </FormControl.Caption>
              </FormControl>
            </div>
          </Stack>
          <Stack gap="normal">
            <Stack gap="none">
              <Text size="medium" weight="semibold" id="permissions-section-label">
                Add permissions
              </Text>
              <Text size="medium" className="fgColor-muted" id="permissions-section-description">
                {addPermissionsText}
              </Text>
            </Stack>
            <PermissionsPicker
              availablePermissions={availablePermissions}
              availableBaseRoles={availableBaseRoles}
              targetTypes={targetTypes}
              selectedFgpsByTarget={selectedFgpsByTarget}
              setSelectedFgpsByTarget={setSelectedFgpsByTarget}
              selectedBaseRoleByTarget={selectedBaseRoleByTarget}
              setSelectedBaseRoleByTarget={setSelectedBaseRoleByTarget}
            />
          </Stack>
          <Stack direction="horizontal" gap="condensed">
            <Button variant="primary" type="submit" loading={isPending} disabled={isPending || isSuccess}>
              {submitButtonText}
            </Button>
            <Button variant="default" onClick={handleCancel} disabled={isPending || isSuccess}>
              {cancelButtonText}
            </Button>
          </Stack>
        </Stack>
      </form>
      {role && isConfirmationDialogOpen && (
        <RoleUpdateConfirmationDialog
          role={role}
          onCancel={() => setIsConfirmationDialogOpen(false)}
          onUpdateRole={performSubmit}
        />
      )}
    </>
  )
}
